<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Request received · Cerberus</title>
<style>:root{--ink:#142238;--navy:#182329;--gold:#b48b43;--paper:#252a2e;--muted:#657080}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 20%,#555b60,#252a2e 65%);color:var(--ink);font:13px/1.4 Inter,ui-sans-serif,system-ui,sans-serif;display:grid;place-items:center;padding:20px 10px}.card{position:relative;overflow:hidden;background:#fff;border:1px solid #e5e0d4;border-radius:13px;padding:30px 28px 27px;max-width:620px;width:100%;text-align:center;box-shadow:0 20px 50px #0006}.card:before,.card:after{content:"";position:absolute;width:180px;height:115px;border-radius:50%;background:#eef4e8;opacity:.9;transform:rotate(-25deg);top:-65px;left:-80px}.card:after{top:auto;left:auto;right:-85px;bottom:-70px;background:#f3efe8;transform:rotate(30deg)}.card>*{position:relative;z-index:1}.mark{width:58px;height:58px;margin:auto;border-radius:50%;background:#c9f0ca;color:#277b35;display:grid;place-items:center;font-size:35px;line-height:1;box-shadow:0 0 0 8px #edf8ee,0 0 0 15px #f5fbf5}.eyebrow{color:#987335;letter-spacing:.2em;font-size:9px;font-weight:800;margin-top:30px}.card h1{font-size:clamp(26px,4vw,38px);line-height:1.05;margin:10px 0 14px;letter-spacing:-.04em}.card h1 .name{color:#a27932}.intro{max-width:490px;margin:0 auto;color:#5c6878;font-size:15px;line-height:1.4}.demo-note{max-width:520px;margin:17px auto;padding:13px 16px;border-radius:11px;background:#f7f5f1;color:#5c6878;text-align:left;font-size:13px}.demo-note strong{color:#956f2e}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);margin:17px 0;border:1px solid #e1e4e8;border-radius:11px;text-align:left}.summary-item{display:flex;align-items:center;gap:8px;padding:13px 10px;border-right:1px solid #e1e4e8}.summary-item:last-child{border-right:0}.summary-icon{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#edf7ee;font-size:16px}.summary-label{display:block;color:#6a7483;font-size:8px;letter-spacing:.06em;text-transform:uppercase}.summary-value{display:block;color:var(--ink);font-size:13px;font-weight:800;margin-top:3px}.ref{background:var(--navy);color:white;padding:9px;border-radius:7px;margin:13px auto;max-width:410px}.ref small{display:block;color:#d3bc81;letter-spacing:.08em;font-size:10px}.ref strong{font-size:14px;letter-spacing:.05em}.options{list-style:none;padding:0;color:var(--muted);margin:11px 0}.button{display:block;margin:17px auto 0;max-width:440px;background:linear-gradient(#c09a56,#9b7129);color:white;font-size:15px;font-weight:800;text-decoration:none;padding:11px 16px;border-radius:8px;box-shadow:0 3px 0 #76531e}@media(max-width:700px){body{padding:10px 6px}.card{padding:25px 14px 23px}.eyebrow{margin-top:27px;font-size:8px}.intro{font-size:14px}.demo-note{font-size:12px;padding:11px 13px}.summary-grid{grid-template-columns:1fr}.summary-item{border-right:0;border-bottom:1px solid #e1e4e8;padding:11px}.summary-item:last-child{border-bottom:0}.button{font-size:14px}}
</style><style>.card{max-width:500px}</style></head>
<body><main class="card"><div class="mark" aria-hidden="true">✓</div><div class="eyebrow">REQUEST RECEIVED</div><h1>Thank you, <span class="name">{{ $booking->customer->full_name ?? 'your request is with us' }}</span>.</h1><p class="intro">Your {{ $booking->package->name }} inspection request has been recorded. Your preferred appointment times are not confirmed yet; our team will contact you to agree a time.</p>@if($booking->package->is_demo)<p class="demo-note"><strong>LOCAL DEMO:</strong> Package and quote are sample values for application testing, not an approved customer offer.</p>@endif @if (session('email_delivery_failed'))<p class="demo-note">Your request is recorded, but we could not send the acknowledgement email just now. Please keep this reference.</p>@endif<div class="summary-grid"><div class="summary-item"><span class="summary-icon">🚗</span><span><span class="summary-label">Vehicle</span><strong class="summary-value">{{ $booking->vehicle->registration }}</strong></span></div><div class="summary-item"><span class="summary-icon">▤</span><span><span class="summary-label">Estimated quote</span><strong class="summary-value">{{ $booking->currency }} {{ number_format((float) $booking->quoted_total, 2) }}</strong></span></div><div class="summary-item"><span class="summary-icon">▣</span><span><span class="summary-label">Preferred time</span><strong class="summary-value">{{ $booking->preferences->first()?->preferred_at->format('D j M Y') }}<br>{{ $booking->preferences->first()?->preferred_at->format('H:i') }}</strong></span></div></div><div class="ref"><small>BOOKING REFERENCE</small><strong>{{ $booking->booking_reference }}</strong></div><ul class="options">@foreach ($booking->preferences as $preference)@if($preference->priority > 1)<li>Option {{ $preference->priority }}: {{ $preference->preferred_at->format('D j M Y, H:i') }}</li>@endif @endforeach</ul><a class="button" href="{{ route('home') }}">← &nbsp; Return to Cerberus</a></main></body>
</html>
